tool_input_args.value:
cd /workspace && node -e "
const XLSX = require('xlsx');
const { Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, Table, TableRow, TableCell, WidthType, BorderStyle } = require('docx');
const fs = require('fs');

// --- Read data ---
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
const orders = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

// --- Analysis ---
const totalOrders = orders.length;
const confirmed = orders.filter(o => o.Status === 'confirmed');
const cancelled = orders.filter(o => o.Status === 'cancelled');
const totalRevenue = confirmed.reduce((s, o) => s + o['Total Paid'], 0);
const cancelledValue = cancelled.reduce((s, o) => s + o['Total Paid'], 0);
const avgOrderValue = (totalRevenue / confirmed.length).toFixed(2);

// Customer breakdown
const customerOrders = {};
const customerSpend = {};
confirmed.forEach(o => {
  customerOrders[o.Customer] = (customerOrders[o.Customer] || 0) + 1;
  customerSpend[o.Customer] = (customerSpend[o.Customer] || 0) + o['Total Paid'];
});
const topCustomerByOrders = Object.entries(customerOrders).sort((a,b) => b[1]-a[1]);
const topCustomerBySpend = Object.entries(customerSpend).sort((a,b) => b[1]-a[1]);

// Product frequency
const productCount = {};
confirmed.forEach(o => {
  o.Items.split(', ').forEach(item => {
    productCount[item] = (productCount[item] || 0) + 1;
  });
});
const topProducts = Object.entries(productCount).sort((a,b) => b[1]-a[1]);

// Date breakdown
const dateOrders = {};
confirmed.forEach(o => {
  dateOrders[o.Date] = (dateOrders[o.Date] || 0) + 1;
});

// Unique customers
const uniqueCustomers = new Set(orders.map(o => o.Customer)).size;

// --- Build Word Doc ---
const b = (text) => new TextRun({ text, bold: true });
const t = (text) => new TextRun({ text });
const br = () => new TextRun({ text: '', break: 1 });

const doc = new Document({
  sections: [{
    properties: {},
    children: [
      new Paragraph({
        text: 'Order Summary Analysis',
        heading: HeadingLevel.TITLE,
        alignment: AlignmentType.CENTER,
        spacing: { after: 200 },
      }),
      new Paragraph({
        children: [t('Report generated from: testbed/data/order_summary.xlsx')],
        spacing: { after: 200 },
        alignment: AlignmentType.CENTER,
      }),

      // --- Overview ---
      new Paragraph({ text: '1. Overview', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 100 } }),
      new Paragraph({ children: [b('Total Orders: '), t(String(totalOrders))], spacing: { after: 60 } }),
      new Paragraph({ children: [b('Confirmed Orders: '), t(String(confirmed.length) + ' (' + ((confirmed.length/totalOrders)*100).toFixed(1) + '%)')], spacing: { after: 60 } }),
      new Paragraph({ children: [b('Cancelled Orders: '), t(String(cancelled.length) + ' (' + ((cancelled.length/totalOrders)*100).toFixed(1) + '%)')], spacing: { after: 60 } }),
      new Paragraph({ children: [b('Unique Customers: '), t(String(uniqueCustomers))], spacing: { after: 60 } }),
      new Paragraph({ children: [b('Order Date Range: '), t([...new Set(orders.map(o=>o.Date))].sort().join(' to '))], spacing: { after: 60 } }),

      // --- Revenue ---
      new Paragraph({ text: '2. Revenue Summary', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 100 } }),
      new Paragraph({ children: [b('Total Confirmed Revenue: '), t('\$' + totalRevenue.toLocaleString())], spacing: { after: 60 } }),
      new Paragraph({ children: [b('Lost Revenue (Cancelled): '), t('\$' + cancelledValue.toLocaleString())], spacing: { after: 60 } }),
      new Paragraph({ children: [b('Average Order Value (Confirmed): '), t('\$' + avgOrderValue)], spacing: { after: 60 } }),
      new Paragraph({ children: [b('Highest Single Order: '), t('\$' + Math.max(...confirmed.map(o=>o['Total Paid'])) + ' (Order ' + confirmed.sort((a,b)=>b['Total Paid']-a['Total Paid'])[0]['Order ID'] + ')')], spacing: { after: 60 } }),
      new Paragraph({ children: [b('Lowest Single Order: '), t('\$' + Math.min(...confirmed.map(o=>o['Total Paid'])) + ' (Order ' + confirmed.sort((a,b)=>a['Total Paid']-b['Total Paid'])[0]['Order ID'] + ')')], spacing: { after: 60 } }),

      // --- By Date ---
      new Paragraph({ text: '3. Orders by Date', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 100 } }),
      ...Object.entries(dateOrders).sort().map(([date, count]) =>
        new Paragraph({ children: [b(date + ': '), t(count + ' confirmed orders')], spacing: { after: 60 } })
      ),

      // --- Top Customers ---
      new Paragraph({ text: '4. Top Customers by Spend', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 100 } }),
      ...topCustomerBySpend.slice(0, 10).map(([name, spend], i) =>
        new Paragraph({
          children: [b((i+1) + '. ' + name + ': '), t('\$' + spend + ' (' + customerOrders[name] + ' orders)')],
          spacing: { after: 60 }
        })
      ),

      // --- Top Products ---
      new Paragraph({ text: '5. Most Popular Products (by order frequency)', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 100 } }),
      ...topProducts.map(([product, count], i) =>
        new Paragraph({
          children: [b((i+1) + '. ' + product + ': '), t('appeared in ' + count + ' confirmed orders')],
          spacing: { after: 60 }
        })
      ),

      // --- Cancelled Orders ---
      new Paragraph({ text: '6. Cancelled Orders Detail', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 100 } }),
      ...cancelled.map(o =>
        new Paragraph({
          children: [b(o['Order ID'] + ' — '), t(o.Customer + ' — ' + o.Items + ' — \$' + o['Total Paid'])],
          spacing: { after: 60 }
        })
      ),

      // --- Key Takeaways ---
      new Paragraph({ text: '7. Key Takeaways', heading: HeadingLevel.HEADING_1, spacing: { before: 300, after: 100 } }),
      new Paragraph({ children: [t('• The confirmation rate is strong at ' + ((confirmed.length/totalOrders)*100).toFixed(1) + '%, with only ' + cancelled.length + ' cancellations out of ' + totalOrders + ' orders.')], spacing: { after: 60 } }),
      new Paragraph({ children: [t('• Maya Chen is the most active and highest-spending customer, accounting for \$' + customerSpend['Maya Chen'] + ' in confirmed revenue across ' + customerOrders['Maya Chen'] + ' orders.')], spacing: { after: 60 } }),
      new Paragraph({ children: [t('• The LogiTech Wireless Mouse M310 is the most frequently ordered product, appearing in ' + productCount['LogiTech Wireless Mouse M310'] + ' confirmed orders.')], spacing: { after: 60 } }),
      new Paragraph({ children: [t('• All cancelled orders belong to only ' + new Set(cancelled.map(o=>o.Customer)).size + ' customer(s), which may warrant further investigation.')], spacing: { after: 60 } }),
      new Paragraph({ children: [t('• Average confirmed order value of \$' + avgOrderValue + ' suggests healthy basket sizes with many multi-item orders.')], spacing: { after: 60 } }),
    ]
  }]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('order_analysis.docx', buf);
  console.log('✅ Saved: /workspace/order_analysis.docx (' + buf.length + ' bytes)');
});
"
